package com.climbme.app.training;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.csrf;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.climbme.app.ClimbMeApplication;import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.*;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.http.MediaType;import org.springframework.mock.web.MockHttpSession;import org.springframework.test.web.servlet.*;import org.springframework.transaction.annotation.Transactional;
@SpringBootTest(classes=ClimbMeApplication.class,properties={"spring.datasource.url=jdbc:h2:mem:climbme_training;MODE=PostgreSQL;DB_CLOSE_DELAY=-1;DATABASE_TO_LOWER=TRUE","spring.datasource.username=sa","spring.datasource.password=","spring.jpa.hibernate.ddl-auto=validate"})@AutoConfigureMockMvc @Transactional class TrainingIntegrationTest{@Autowired MockMvc mvc;@Test void ownerCanManageTrainingButAnotherUserCannotReadIt()throws Exception{MockHttpSession owner=register("training-owner@example.com"),other=register("training-other@example.com");MvcResult result=mvc.perform(post("/api/training").session(owner).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(payload())).andExpect(status().isCreated()).andReturn();long id=Long.parseLong(result.getResponse().getContentAsString().replaceAll(".*\\\"id\\\":(\\d+).*","$1"));mvc.perform(get("/api/training").session(owner)).andExpect(jsonPath("$[0].sessionType").value("HANGBOARD"));mvc.perform(delete("/api/training/{id}",id).session(other).with(csrf())).andExpect(status().isNotFound());}MockHttpSession register(String email)throws Exception{MvcResult r=mvc.perform(post("/api/auth/register").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"email\":\""+email+"\",\"password\":\"safe-password-123\"}")).andReturn();return(MockHttpSession)r.getRequest().getSession(false);}String payload(){return "{\"trainedOn\":\"2026-08-12\",\"sessionType\":\"HANGBOARD\",\"durationMinutes\":45,\"strength\":8,\"endurance\":6}";}}
